<?php
require_once __DIR__.'/includes/functions.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();require_once __DIR__.'/config/database.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$stmt=$pdo->prepare('SELECT * FROM products WHERE id = :id');$stmt->execute(['id'=>$id?:0]);$product=$stmt->fetch();
if(!$product){http_response_code(404);$pageTitle='Өнім табылмады';require __DIR__.'/includes/header.php';echo '<section class="empty-state page-empty"><p class="eyebrow">404</p><h1>Өнім табылмады.</h1><p>Сілтемені тексеріңіз немесе каталогқа оралыңыз.</p><a class="button button-dark" href="products.php">Каталогқа өту</a></section>';require __DIR__.'/includes/footer.php';exit;}
$pageTitle=$product['name'].' — Apple Store';require __DIR__.'/includes/header.php';
?>
<section class="product-detail section-pad"><div class="detail-visual"><?= product_image($product,'detail-image') ?><span class="image-placeholder"></span></div><div class="detail-copy"><a class="text-link" href="products.php">← Каталог</a><p class="eyebrow"><?= e($product['category']) ?></p><h1><?= e($product['name']) ?></h1><p class="detail-description"><?= e($product['description']) ?></p><p class="detail-price"><?= money($product['price']) ?></p><p class="stock-note"><?= (int)$product['stock']>0?'Қолжетімді: '.(int)$product['stock'].' дана':'Қазір қолжетімсіз' ?></p><?php if((int)$product['stock']>0): ?><form action="cart.php" method="post" class="add-cart-form"><?= csrf_field() ?><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><label>Саны<input type="number" name="quantity" min="1" max="<?= (int)$product['stock'] ?>" value="1"></label><button class="button button-dark" type="submit">Себетке қосу</button></form><?php else: ?><button class="button button-muted" disabled>Қолжетімсіз</button><?php endif; ?><p class="fine-print">Бағалар мен сипаттамалар оқу жобасына арналған демонстрациялық деректер.</p></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
